            int remainingToUse = pointsToUse;
            int totalUsed = 0;

            for (Point point : availablePoints) {
                if (remainingToUse <= 0) break;

                Integer usedAmount = point.use(remainingToUse);
                int used = usedAmount != null ? usedAmount : 0;
                remainingToUse -= used;
                totalUsed += used;

                // 포인트 사용 이유 추가
                if (used > 0) {
